import{c as a,Q as s,j as i,m as t}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"Internet bridge","description":"","frontmatter":{},"headers":[],"relativePath":"docs/bridge.md","filePath":"docs/bridge.md"}'),n={name:"docs/bridge.md"};function r(l,e,o,p,d,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="internet-bridge" tabindex="-1">Internet bridge <a class="header-anchor" href="#internet-bridge" aria-label="Permalink to &quot;Internet bridge&quot;">​</a></h1><h2 id="purpose-of-the-bridge-system" tabindex="-1">Purpose of the bridge system <a class="header-anchor" href="#purpose-of-the-bridge-system" aria-label="Permalink to &quot;Purpose of the bridge system&quot;">​</a></h2><p>MeshCoreNG is RF-first. The bridge system is optional transport/backhaul for specific deployments, not a replacement for RF-local operation.</p><p>Bridges are intended for:</p><ul><li>Linking isolated geographic MeshCore RF regions that should intentionally exchange selected traffic.</li><li>Remote RF gateways that need a controlled backhaul path.</li><li>Temporary backhaul during events, tests, or outages.</li><li>Observer, measurement, and research setups.</li><li>Private infrastructure operated by a known group.</li></ul><p>Bridges are not intended for:</p><ul><li>A worldwide flooding backbone.</li><li>An always-on global relay.</li><li>Unrestricted packet replication.</li><li>Bypassing normal RF planning and segmentation.</li></ul><p>Selected traffic can optionally be transported between isolated MeshCore deployments. Bridge operators decide which bridge server, repeaters, regions, and traffic sources are appropriate for their network.</p><h2 id="intended-usage" tabindex="-1">Intended usage <a class="header-anchor" href="#intended-usage" aria-label="Permalink to &quot;Intended usage&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph A[&quot;Island A: local RF deployment&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A1[&quot;LoRa clients&quot;] &lt;--&gt; A2[&quot;RF repeaters&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A2 &lt;--&gt; A3[&quot;Bridge repeater&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A3 &lt;--&gt; S[&quot;Private or controlled bridge server&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph B[&quot;Island B: local RF deployment&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B3[&quot;Bridge repeater&quot;] &lt;--&gt; B2[&quot;RF repeaters&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B2 &lt;--&gt; B1[&quot;LoRa clients&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S &lt;--&gt; B3</span></span></code></pre></div><p>The bridge is a controlled link between selected RF islands. Each island should still be designed as a sensible local RF network.</p><h2 id="not-intended" tabindex="-1">Not intended <a class="header-anchor" href="#not-intended" aria-label="Permalink to &quot;Not intended&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G[&quot;Single worldwide bridge group&quot;]:::bad</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    N1[&quot;Region A&quot;] --&gt; G</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    N2[&quot;Region B&quot;] --&gt; G</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    N3[&quot;Region C&quot;] --&gt; G</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    N4[&quot;Region D&quot;] --&gt; G</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt; F[&quot;Unrestricted packet replication&quot;]:::bad</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; N1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; N2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; N3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; N4</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    classDef bad fill:#ffe7e7,stroke:#b00020,color:#111</span></span></code></pre></div><p>Large-scale uncontrolled forwarding is discouraged. It wastes RF airtime, makes loops harder to reason about, and works against MeshCoreNG&#39;s goal of keeping busy radio networks calm.</p><h2 id="rf-locality-remains-important" tabindex="-1">RF locality remains important <a class="header-anchor" href="#rf-locality-remains-important" aria-label="Permalink to &quot;RF locality remains important&quot;">​</a></h2><p>RF airtime efficiency remains a primary MeshCoreNG design goal. Internet transport should not be used to bypass sensible RF segmentation.</p><p>Operators should bridge only what is needed for the deployment. Keep local traffic local where possible, use regional segmentation, and avoid forwarding traffic into RF areas that do not need it.</p><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li>Bridge only required channels, topics, or traffic sources.</li><li>Avoid unnecessary rebroadcast into RF networks.</li><li>Use regional segmentation for large deployments.</li><li>Use private bridge groups or private bridge servers when possible.</li><li>Avoid full-network flooding across bridge links.</li><li>Monitor airtime, duplicate counters, and congestion after enabling a bridge.</li><li>Treat every bridge as an operated network service with an owner and a purpose.</li></ul><h2 id="planned-loop-and-duplicate-protections" tabindex="-1">Planned loop and duplicate protections <a class="header-anchor" href="#planned-loop-and-duplicate-protections" aria-label="Permalink to &quot;Planned loop and duplicate protections&quot;">​</a></h2><p>Multi-bridge environments need additional safeguards because the same packet may be able to return through a different bridge path.</p><p>Planned or under consideration protections include:</p><ul><li>Path fingerprints.</li><li>Lightweight path hashes.</li><li>Bridge loop detection.</li><li>Duplicate suppression.</li><li>TTL and hop controls.</li><li>Bridge scoping.</li></ul><p>These mechanisms are intended to make controlled bridge deployments safer. They do not change the basic guidance: avoid uncontrolled forwarding, keep bridge groups scoped, and preserve RF locality.</p><h2 id="path-1-esp32-repeater-with-wifi" tabindex="-1">Path 1: ESP32 repeater with WiFi <a class="header-anchor" href="#path-1-esp32-repeater-with-wifi" aria-label="Permalink to &quot;Path 1: ESP32 repeater with WiFi&quot;">​</a></h2><p>Flash a <code>_bridge_tcp</code> firmware variant on an ESP32 repeater that has WiFi, then configure it for the selected bridge server:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set wifi.ssid     YourWiFi</span></span>
<span class="line"><span>set wifi.password secret123</span></span>
<span class="line"><span>set bridge.server yourserver.example.com</span></span>
<span class="line"><span>set bridge.port   4200</span></span>
<span class="line"><span>set bridge.enabled on</span></span></code></pre></div><p>Check the bridge type:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get bridge.type</span></span></code></pre></div><h2 id="path-2-repeater-via-usb" tabindex="-1">Path 2: Repeater via USB <a class="header-anchor" href="#path-2-repeater-via-usb" aria-label="Permalink to &quot;Path 2: Repeater via USB&quot;">​</a></h2><p>Boards without WiFi, including nRF52 (RAK4631), RP2040, STM32, or ESP32 boards without WiFi access, can use a USB-connected PC or Raspberry Pi as the bridge transport host.</p><p>Flash the <code>_bridge_rs232</code> firmware variant and enable the bridge:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.enabled on</span></span></code></pre></div><p>Then run the relay script on the connected computer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pyserial</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/usb_bridge_client.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --serial</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --baud</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 115200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                                    --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourserver.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span></span></code></pre></div><p>On Windows use <code>--serial COM3</code>.</p><h2 id="running-the-server" tabindex="-1">Running the server <a class="header-anchor" href="#running-the-server" aria-label="Permalink to &quot;Running the server&quot;">​</a></h2><p>Start the TCP bridge server on a machine the intended bridge repeaters can reach:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span></span></code></pre></div><p>No external dependencies. WiFi repeaters and USB repeaters can connect to the same controlled bridge server simultaneously.</p><h2 id="security-note" tabindex="-1">Security note <a class="header-anchor" href="#security-note" aria-label="Permalink to &quot;Security note&quot;">​</a></h2><p>The current TCP bridge does not encrypt traffic. Run the server on a trusted network or VPS with firewall rules limiting access. TLS support is planned for a future release.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Does MeshCoreNG require internet?</strong><br> No. MeshCoreNG remains usable as an RF-only LoRa mesh.</p><p><strong>Is the bridge enabled by default?</strong><br> No. Bridge support requires a bridge-capable firmware build and <code>set bridge.enabled on</code>.</p><p><strong>Is this intended to create a global internet mesh?</strong><br> No. The bridge is for controlled transport between selected deployments, not worldwide packet propagation.</p><p><strong>Can bridges be private?</strong><br> Yes. Private bridge servers and private bridge groups are recommended for many deployments.</p><p><strong>Are anti-loop protections planned?</strong><br> Yes. Path fingerprints, lightweight path hashes, loop detection, duplicate suppression, TTL/hop controls, and bridge scoping are planned or being evaluated, especially for multi-bridge environments.</p>`,48)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
